def daily_net(month, client):
    begin, end = ledger_month_window(month)
    rows = client.list_transactions(created_from=begin, created_to=end)
    days = {}
    for row in rows:
        ledger_date = (parse_timestamp(row["posted_at"]) - timedelta(hours=5)).date().isoformat()
        if ledger_date not in days:
            days[ledger_date] = {"payment_total_cents": 0, "refund_total_cents": 0}
        if row["kind"] == "payment":
            days[ledger_date]["payment_total_cents"] += row["amount_cents"]
        else:
            days[ledger_date]["refund_total_cents"] += row["amount_cents"]
    result_days = []
    for date in sorted(days):
        p = days[date]["payment_total_cents"]
        r = days[date]["refund_total_cents"]
        result_days.append({"date": date, "payment_total_cents": p, "refund_total_cents": r, "net_total_cents": p - r})
    return {"month": month, "days": result_days}


